package com.audiobookdownloader;
import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;
/** Native transfer screen remains usable independently of the Compose player. */
public final class CollectionTransferActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private CollectionTransferStore store;private LegacyCollectionsBridge bridge;private TextView status;private Button direct,open,export,apply,undo,screenStart,screenFinish;private String pending;private boolean working;
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(LinearLayout root,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(0,dp(8),0,dp(8));root.addView(t);return t;}
 private Button button(LinearLayout root,String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(0xfff2d2a4);GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff253144,0xff121925});bg.setCornerRadius(dp(18));bg.setStroke(dp(1),0xffbb925d);b.setBackground(bg);b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(54));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);root.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new CollectionTransferStore(this);getWindow().setStatusBarColor(0xff101725);getWindow().setNavigationBarColor(0xff101725);ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xff101725);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(20),dp(22),dp(28));root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(22),dp(20)+insets.getSystemWindowInsetTop(),dp(22),dp(28)+insets.getSystemWindowInsetBottom());return insets;});scroll.addView(root);setContentView(scroll);
  text(root,"Перенос коллекций",25).setTypeface(null,Typeface.BOLD);text(root,"Добавьте коллекции из старой Audiobook или сохранённого JSON/XML. Перенос дополняет текущие коллекции. Старая версия и аудиофайлы не изменяются.",15);
  String eligibility=LegacyCollectionsBridge.eligibility(this);status=text(root,eligibility==null?"Старая Audiobook найдена. Для прямого чтения нужно однократное разрешение Shizuku. Доступ к аудиопапке не открывает закрытые настройки приложения.":eligibility,14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);
  direct=button(root,"Считать коллекции из старой Audiobook",this::readLegacy);direct.setEnabled(eligibility==null);
  if(eligibility==null){
  button(root,"Открыть / установить Shizuku",this::openShizuku);
  text(root,"Прямой перенос: установите официальный Shizuku, запустите его через беспроводную отладку по инструкции внутри Shizuku, затем вернитесь и нажмите «Считать». Разрешение запрашивается только по вашему действию. Читаются только коллекции.",13);
  button(root,"Инструкция запуска Shizuku",()->browse("https://shizuku.rikka.app/guide/setup/#start-via-wireless-debugging"));
  }
  text(root,"Если закрытые данные прочитать нельзя",18);
  text(root,"Можно перенести названия полок и книг с экранов старой Audiobook. Откройте там «Коллекции», прокрутите весь список полок, затем откройте каждую и прокрутите все её книги. Переносятся только полностью просмотренные полки. Ссылки и обложки с экрана не читаются; скачанные книги находятся по названию. Это перенос по запросу, без фоновой синхронизации.",14);
  screenStart=button(root,"Начать перенос с экранов",this::beginScreens);
  button(root,"Открыть старую Audiobook",()->{try{Intent i=getPackageManager().getLaunchIntentForPackage(LegacyCollectionsReader.LEGACY);if(i==null)throw new IllegalStateException();startActivity(i);}catch(Exception e){status.setText("Старая Audiobook не найдена");}});
  screenFinish=button(root,"Завершить чтение экранов и проверить",()->{LegacyCollectionScreens data=LegacyCollectionsScreenService.snapshot();LegacyCollectionsScreenService.finish();if(data==null){status.setText("Сначала начните перенос с экранов");return;}int partial=data.partial();run(()->{if(data.complete()==0)throw new IllegalArgumentException("Нет полностью просмотренных коллекций. Откройте общий список полок, затем каждую полку и прокрутите до конца. Неполных полок: "+partial);return stage(data.export())+" Неполных полок пропущено: "+partial+". Ссылки и обложки с экрана не переносились.";});});
  text(root,"Android попросит включить «Перенос коллекций Audiobook» в специальных возможностях. Это разрешение на чтение экранов. Мы читаем только старую Audiobook в течение 10 минут, без нажатий и изменений. Если Android блокирует включение: настройки телефона → приложения → новая Audiobook → ⋮ → разрешить ограниченные настройки. По завершении служба отключается.",13);
  open=button(root,"Импортировать JSON/XML",()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/plain","text/xml","application/xml","application/octet-stream"});try{startActivityForResult(intent,51);}catch(Exception e){status.setText("Не удалось открыть выбор файла");}});
  apply=button(root,"Добавить найденные коллекции",this::apply);apply.setEnabled(false);
  export=button(root,"Сохранить копию коллекций",()->{String name="Audiobook-collections-"+new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date())+".json";try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,name),52);}catch(Exception e){status.setText("Не удалось открыть сохранение файла");}});
  undo=button(root,"Отменить последний импорт",()->run(()->{store.undo();return "Коллекции восстановлены из копии перед импортом";}));undo.setEnabled(store.canUndo());text(root,"Копия перед последним импортом сохраняется внутри приложения. Отмена доступна, пока коллекции не менялись после переноса. Повторный импорт не создаёт дубликатов.",13);
 }
 private void beginScreens(){if(working)return;pending=null;LegacyCollectionsScreenService.begin();apply.setEnabled(false);status.setText("Включите «Перенос коллекций Audiobook», затем откройте старую Audiobook и просмотрите коллекции. Вернитесь сюда и завершите чтение экранов. Сеанс ограничен 10 минутами.");try{startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception e){LegacyCollectionsScreenService.clear();status.setText("Откройте специальные возможности в настройках Android");}}
 private interface Task{String work()throws Exception;}
 private void busy(boolean value){working=value;screenStart.setEnabled(!value);screenFinish.setEnabled(!value);open.setEnabled(!value);export.setEnabled(!value);direct.setEnabled(!value&&LegacyCollectionsBridge.eligibility(this)==null);apply.setEnabled(!value&&pending!=null);undo.setEnabled(!value&&store.canUndo());}
 private void run(Task task){busy(true);status.setText("Подождите…");worker.submit(()->{String result;try{result=task.work();}catch(Exception e){result=e instanceof IllegalArgumentException||e instanceof IOException?e.getMessage():"Не удалось обработать коллекции. Проверьте файл и повторите попытку";}String message=result;runOnUiThread(()->{if(isDestroyed()||isFinishing())return;busy(false);status.setText(message);});});}
 private String stage(String document)throws Exception{String normalized=CollectionTransferRules.export(document);var result=store.preview(normalized);pending=normalized;return "Найдено коллекций: "+CollectionTransferRules.parse(normalized).length()+". Новых коллекций: "+result.addedShelves+", книг: "+result.addedBooks+". Нажмите «Добавить найденные коллекции» для переноса.";}
 private void apply(){if(pending==null)return;String data=pending;run(()->{var result=store.apply(data);pending=null;LegacyCollectionsScreenService.clear();return "Добавлено коллекций: "+result.addedShelves+", книг: "+result.addedBooks+". Дополнено ссылок/обложек: "+result.filledReferences+".";});}
 private void readLegacy(){pending=null;if(bridge!=null)bridge.close();busy(true);status.setText("Подключаемся к старой Audiobook…");bridge=new LegacyCollectionsBridge(this);bridge.start((data,error)->{if(isDestroyed()||isFinishing())return;if(error!=null){busy(false);status.setText(error);}else run(()->stage(data));});}
 private void openShizuku(){try{Intent intent=getPackageManager().getLaunchIntentForPackage("moe.shizuku.privileged.api");if(intent!=null)startActivity(intent);else browse("https://shizuku.rikka.app/download/");}catch(Exception e){browse("https://shizuku.rikka.app/download/");}}
 private void browse(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){status.setText("Откройте официальный сайт shizuku.rikka.app в браузере");}}
 static String read(InputStream in)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>CollectionTransferRules.MAX_BYTES)throw new IllegalArgumentException("Файл коллекций слишком большой");out.write(b,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==51){pending=null;run(()->stage(read(getContentResolver().openInputStream(uri))));}else if(request==52)run(()->{String json=CollectionTransferRules.export(store.current());try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Не удалось открыть файл");out.write(json.getBytes(StandardCharsets.UTF_8));}return "Копия коллекций сохранена";});}
 @Override protected void onDestroy(){if(bridge!=null)bridge.close();worker.shutdownNow();super.onDestroy();}
}
